import React from "react";
import { useQuery } from "@tanstack/react-query";
import { useAuthStore } from "@/stores/authStore";
import { User, Plus, Shield, Search, Edit3, Trash2 } from "lucide-react";
import userService from "@/services/userService";

const roleLabels: Record<string, string> = {
  administrador: "Administrador",
  supervisor: "Supervisor",
  operador: "Operador",
};

const roleColors: Record<string, string> = {
  administrador: "text-invicorp-accent",
  supervisor: "text-invicorp-warn",
  operador: "text-invicorp-text",
};

export function Users() {
  const { business } = useAuthStore();

  const { data, isLoading } = useQuery({
    queryKey: ["users", business?.id],
    queryFn: () => userService.list({ page: 1, pageSize: 50 }),
    enabled: !!business?.id,
  });

  const users = data?.data || [];

  if (isLoading) {
    return (
      <div className="page-container flex flex-col items-center justify-center py-20">
        <div className="w-8 h-8 border-4 border-invicorp-accent/30 border-t-full rounded-full animate-spin mb-4" />
        <p className="text-invicorp-muted">Cargando usuarios...</p>
      </div>
    );
  }

  return (
    <div className="page-container">
      <div className="section-header">
        <div>
          <h1 className="text-2xl font-bold text-invicorp-text">Usuarios y permisos</h1>
          <p className="text-invicorp-muted">Gestiona el acceso de tu equipo</p>
        </div>
        <button className="btn-primary flex items-center gap-2">
          <Plus className="w-4 h-4" /> Nuevo usuario
        </button>
      </div>

      <div className="glass-panel rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-invicorp-panel2/50">
              <tr>
                <th className="px-4 py-3 text-xs font-medium text-invicorp-muted uppercase">Usuario</th>
                <th className="px-4 py-3 text-xs font-medium text-invicorp-muted uppercase">Correo</th>
                <th className="px-4 py-3 text-xs font-medium text-invicorp-muted uppercase">Rol</th>
                <th className="px-4 py-3 text-xs font-medium text-invicorp-muted uppercase">Estado</th>
                <th className="px-4 py-3 text-xs font-medium text-invicorp-muted uppercase">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-invicorp-line">
              {users.length > 0 ? (
                users.map((u: any) => (
                  <tr key={u.id} className="hover:bg-invicorp-line/30 transition-colors">
                    <td className="px-4 py-3 text-sm text-invicorp-text">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-invicorp-panel border border-invicorp-line flex items-center justify-center text-invicorp-muted">
                          {u.full_name?.charAt(0).toUpperCase() || "U"}
                        </div>
                        <div>
                          <div className="text-sm font-semibold">{u.full_name || "Sin nombre"}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3 text-sm text-invicorp-muted">{u.email || "—"}</td>
                    <td className="px-4 py-3 text-sm">
                      <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium border ${roleColors[u.role]}`}>
                        <Shield className="w-3 h-3" />
                        {roleLabels[u.role] || u.role}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-invicorp-success/10 text-invicorp-success border border-invicorp-success/20">
                        Activo
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex gap-2">
                        <button className="p-2 text-invicorp-accent hover:text-invicorp-accent/80">
                          <Edit3 className="w-4 h-4" />
                        </button>
                        <button className="p-2 text-invicorp-danger hover:text-invicorp-danger/80">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={5} className="px-4 py-12 text-center text-invicorp-muted">
                    <User className="w-8 h-8 mx-auto mb-3 opacity-30" />
                    <p>No hay usuarios registrados</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
